 function applyRepresentingDefaults(values,personOverride=null){const v={...values};const side=v.side||"SELLER";const isBuyer=["BUYER","TENANT"].includes(side);const person=personOverride||(adminMode?(agents.find(a=>a.id===selectedAgentId)||representingAgent):representingAgent);const fullName=[person?.first_name,person?.last_name].filter(Boolean).join(" ")||person?.full_name||person?.name||user?.user_metadata?.full_name||user?.email||"";const agentEmail=person?.email||user?.email||"";const agentPhone=person?.phone||person?.mobile||person?.cell_phone||person?.telephone||"";const brokerageName=companyProfile?.name||companyProfile?.company_name||"DREAM VALLEY REALTY INC., BROKERAGE";const brokerageAddress=[companyProfile?.address,companyProfile?.address_line_1,companyProfile?.street_address,companyProfile?.addr,companyProfile?.city,companyProfile?.province,companyProfile?.postal_code].filter(Boolean).join(", ")||"885 Progress Ave, Suite 109, Toronto, ON M1H 3G3";const brokeragePhone=companyProfile?.phone||companyProfile?.telephone||"416-951-9929";const brokerageFax=companyProfile?.fax||companyProfile?.fax_number||companyProfile?.fax_phone||"647-946-2959";if(isBuyer){v.buyer_brokerage_name=brokerageName;v.buyer_brokerage_address=brokerageAddress;v.buyer_brokerage_phone=brokeragePhone;v.buyer_brokerage_fax=brokerageFax;v.buyer_agent_name=fullName;v.buyer_agent_phone=agentPhone;v.buyer_agent_email=agentEmail;}else{v.listing_brokerage_name=brokerageName;v.listing_brokerage_address=brokerageAddress;v.listing_brokerage_phone=brokeragePhone;v.listing_brokerage_fax=brokerageFax;v.listing_agent_name=fullName;v.listing_agent_phone=agentPhone;v.listing_agent_email=agentEmail;}return v;}
